ngs";a:5:{i:5;i:8441;i:4;i:94;i:3;i:21;i:2;i:16;i:1;i:68;}s:11:"num_ratings";i:8640;s:11:"support_url";s:55:"https://wordpress.org/support/plugin/really-simple-ssl/";s:15:"support_threads";i:34;s:24:"support_threads_resolved";i:33;s:15:"active_installs";i:4000000;s:12:"last_updated";s:21:"2024-09-24 9:44am GMT";s:5:"added";s:10:"2015-03-15";s:8:"homepage";s:29:"https://really-simple-ssl.com";s:8:"sections";a:6:{s:12:"installation";s:548:"<p>Para instalar este plugin:</p>
